// FlowKit · Panel de KPIs — cálculo (Parte 1)
// Lee las hojas Facturas, Onboarding y Docs y devuelve el panel, la fila de histórico y el resumen.
const HOY = new Date();
HOY.setHours(0, 0, 0, 0);
const HOY_MS = HOY.getTime();
const DIA = 86400000;
const NL = String.fromCharCode(10);

function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function r2(n) { return Math.round((Number(n) || 0) * 100) / 100; }
function r1(n) { return Math.round((Number(n) || 0) * 10) / 10; }
function miles(n) {
  const s = r2(n).toFixed(2);
  const p = s.split('.');
  return p[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + p[1];
}
function eur(n) { return miles(n) + ' EUR'; }
function pct(n) { return miles(n) + ' %'; }
function norm(v) {
  return String(v === null || v === undefined ? '' : v)
    .trim().toLowerCase()
    .replace(/[áàä]/g, 'a').replace(/[éèë]/g, 'e').replace(/[íìï]/g, 'i')
    .replace(/[óòö]/g, 'o').replace(/[úùü]/g, 'u');
}
function mk(y, m, d) {
  const dt = new Date(y, m - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== m - 1 || dt.getDate() !== d) return null;
  dt.setHours(0, 0, 0, 0);
  return dt;
}
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date) {
    if (isNaN(v.getTime())) return null;
    return new Date(v.getFullYear(), v.getMonth(), v.getDate());
  }
  if (typeof v === 'number' && isFinite(v)) {
    const d = new Date(Date.UTC(1899, 11, 30) + v * DIA);
    return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  }
  let s = String(v).trim();
  if (!s) return null;
  if (s.length >= 10 && s.charAt(4) === '-') {
    return mk(Number(s.slice(0, 4)), Number(s.slice(5, 7)), Number(s.slice(8, 10)));
  }
  let p = s.split('/');
  if (p.length === 3) return mk(Number(p[2]), Number(p[1]), Number(p[0]));
  p = s.split('-');
  if (p.length === 3) {
    if (p[0].length === 4) return mk(Number(p[0]), Number(p[1]), Number(p[2]));
    return mk(Number(p[2]), Number(p[1]), Number(p[0]));
  }
  const d = new Date(s);
  if (isNaN(d.getTime())) return null;
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}
function parseMoney(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  let s = String(v).trim().replace(/[^0-9,.\-]/g, '');
  if (!s) return 0;
  const neg = s.charAt(0) === '-';
  s = s.replace(/-/g, '');
  const hasC = s.indexOf(',') !== -1;
  const hasD = s.indexOf('.') !== -1;
  if (hasC && hasD) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
    else s = s.replace(/,/g, '');
  } else if (hasC) {
    if (/^\d{1,3}(,\d{3})+$/.test(s)) s = s.replace(/,/g, '');
    else s = s.replace(',', '.');
  } else if (hasD) {
    if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  }
  const n = parseFloat(s);
  if (!isFinite(n)) return 0;
  return neg ? -n : n;
}
function dias(a, b) { return Math.round((b.getTime() - a.getTime()) / DIA); }

function filas(nombre) {
  let items = [];
  try { items = $(nombre).all(); } catch (e) { items = []; }
  return items.map(function (i) { return i.json; })
    .filter(function (r) { return r && Object.keys(r).length > 0; });
}

const facturas = filas('Leer facturas');
const onboarding = filas('Leer onboarding');
const docs = filas('Leer documentos');

// ---------- Cobros ----------
let pendiente = 0, vencido = 0, cobrado30 = 0, nPend = 0, nSinEmail = 0, recCobros30 = 0;
const tramos = { d1: 0, d2: 0, d3: 0, d4: 0 };
const porCliente = {};
let dsoSum = 0, dsoN = 0;

for (const f of facturas) {
  const imp = parseMoney(f.Importe);
  const est = norm(f.Estado);
  const venc = parseDate(f.Fecha_Vencimiento);
  const emi = parseDate(f.Fecha_Emision);
  const pago = parseDate(f.Fecha_Pago);

  if (est === 'pagada') {
    if (pago && pago <= HOY && dias(pago, HOY) <= 30) cobrado30 += imp;
    if (pago && emi && dias(pago, HOY) <= 90) {
      const dd = dias(emi, pago);
      if (dd >= 0 && dd <= 365) { dsoSum += dd; dsoN++; }
    }
    continue;
  }
  if (est === 'incobrable') continue;

  nPend++;
  pendiente += imp;
  if (!String(f.Email || '').trim()) nSinEmail++;

  const ult = parseDate(f.Ultimo_Recordatorio);
  if (ult && dias(ult, HOY) <= 30 && dias(ult, HOY) >= 0) recCobros30++;

  if (venc) {
    const dd = dias(venc, HOY);
    if (dd > 0) {
      vencido += imp;
      if (dd <= 30) tramos.d1 += imp;
      else if (dd <= 60) tramos.d2 += imp;
      else if (dd <= 90) tramos.d3 += imp;
      else tramos.d4 += imp;
      const k = String(f.Cliente || '(sin nombre)').trim() || '(sin nombre)';
      porCliente[k] = (porCliente[k] || 0) + imp;
    }
  }
}

let mayorDeudor = '';
let mayorImporte = 0;
for (const k of Object.keys(porCliente)) {
  if (porCliente[k] > mayorImporte) { mayorImporte = porCliente[k]; mayorDeudor = k; }
}
const pctVencido = pendiente > 0 ? (vencido / pendiente) * 100 : 0;
const dso = dsoN > 0 ? dsoSum / dsoN : 0;
let saludCobro = 'VERDE';
if (vencido > 0 && pctVencido >= 50) saludCobro = 'ROJO';
else if (vencido > 0 && pctVencido >= 25) saludCobro = 'AMBAR';

// ---------- Onboarding ----------
let nOnb = 0, abiertos = 0, completos = 0, sumaAnt = 0, bloqueados = 0, altas30 = 0;
const antServicio = {};

for (const o of onboarding) {
  nOnb++;
  const est = norm(o.Estado);
  const alta = parseDate(o.Fecha_alta);
  const ant = alta ? Math.max(0, dias(alta, HOY)) : 0;

  if (alta && dias(alta, HOY) <= 30 && dias(alta, HOY) >= 0) altas30++;

  if (est === 'completo') { completos++; continue; }

  abiertos++;
  sumaAnt += ant;
  if (alta && ant > 21) bloqueados++;

  const s = norm(o.Servicio) || 'otro';
  if (!antServicio[s]) antServicio[s] = { n: 0, dias: 0 };
  antServicio[s].n++;
  antServicio[s].dias += ant;
}

let servicioLento = '';
let peorMedia = -1;
for (const s of Object.keys(antServicio)) {
  const media = antServicio[s].dias / antServicio[s].n;
  if (media > peorMedia) { peorMedia = media; servicioLento = s; }
}
const antiguedadMedia = abiertos > 0 ? sumaAnt / abiertos : 0;
const tasa = nOnb > 0 ? (completos / nOnb) * 100 : 0;

// ---------- Documentos ----------
let docsPend = 0, docsRec = 0, recDocs30 = 0;
for (const d of docs) {
  const est = norm(d.Estado);
  if (est === 'recibido') { docsRec++; continue; }
  docsPend++;
  const ult = parseDate(d.Ultimo_recordatorio !== undefined ? d.Ultimo_recordatorio : d.Ultimo_Recordatorio);
  if (ult && dias(ult, HOY) <= 30 && dias(ult, HOY) >= 0) recDocs30++;
}
const docsTotal = docsPend + docsRec;
const pctDocs = docsTotal > 0 ? (docsRec / docsTotal) * 100 : 0;

let salud = 'VERDE';
if (saludCobro === 'ROJO') salud = 'ROJO';
else if (saludCobro === 'AMBAR' || bloqueados > 0) salud = 'AMBAR';

// ---------- Panel ----------
const panel = [];
function add(seccion, kpi, valor, unidad, detalle) {
  panel.push({ Seccion: seccion, KPI: kpi, Valor: valor, Unidad: unidad, Detalle: detalle || '' });
}

add('Cobros', 'Facturas pendientes', nPend, 'facturas', '');
add('Cobros', 'Importe pendiente', r2(pendiente), 'EUR', '');
add('Cobros', 'Importe vencido', r2(vencido), 'EUR', '');
add('Cobros', 'Porcentaje vencido', r1(pctVencido), '%', '');
add('Cobros', 'Vencido 1-30 dias', r2(tramos.d1), 'EUR', '');
add('Cobros', 'Vencido 31-60 dias', r2(tramos.d2), 'EUR', '');
add('Cobros', 'Vencido 61-90 dias', r2(tramos.d3), 'EUR', '');
add('Cobros', 'Vencido mas de 90 dias', r2(tramos.d4), 'EUR', '');
add('Cobros', 'Cobrado ultimos 30 dias', r2(cobrado30), 'EUR', '');
add('Cobros', 'Dias medios de cobro', r1(dso), 'dias', 'Facturas pagadas en los ultimos 90 dias');
add('Cobros', 'Mayor deudor', r2(mayorImporte), 'EUR', mayorDeudor || 'Sin deuda vencida');
add('Cobros', 'Facturas sin email', nSinEmail, 'facturas', 'No reciben recordatorio');
add('Cobros', 'Recordatorios de cobro (30 d)', recCobros30, 'facturas', '');
add('Cobros', 'Salud de cobro', 0, '-', saludCobro + ' (' + r1(pctVencido) + ' % vencido)');

add('Clientes', 'Expedientes abiertos', abiertos, 'expedientes', '');
add('Clientes', 'Expedientes completados', completos, 'expedientes', '');
add('Clientes', 'Tasa de finalizacion', r1(tasa), '%', '');
add('Clientes', 'Antiguedad media (abiertos)', r1(antiguedadMedia), 'dias', '');
add('Clientes', 'Bloqueados mas de 21 dias', bloqueados, 'expedientes', 'Requieren llamada');
add('Clientes', 'Documentos pendientes', docsPend, 'documentos', '');
add('Clientes', 'Documentos recibidos', docsRec, 'documentos', '');
add('Clientes', 'Documentacion recibida', r1(pctDocs), '%', '');
add('Clientes', 'Servicio mas lento', r1(peorMedia < 0 ? 0 : peorMedia), 'dias', servicioLento || 'Sin expedientes abiertos');

add('Actividad', 'Altas de clientes (30 d)', altas30, 'expedientes', '');
add('Actividad', 'Recordatorios de documentacion (30 d)', recDocs30, 'documentos', '');
add('Actividad', 'Salud general', 0, '-', salud);
add('Actividad', 'Calculado', 0, '-', iso(HOY));

const historico = {
  Fecha: iso(HOY),
  Pendiente_eur: r2(pendiente),
  Vencido_eur: r2(vencido),
  Pct_vencido: r1(pctVencido),
  Cobrado_30d_eur: r2(cobrado30),
  Facturas_pendientes: nPend,
  Clientes_abiertos: abiertos,
  Docs_pendientes: docsPend,
  Tasa_completado: r1(tasa),
  Bloqueados_21d: bloqueados,
  Salud: salud,
};

let accion = 'Sin alertas: manten el ritmo de cobros y altas.';
if (bloqueados > 0) {
  accion = 'Llama hoy a ' + bloqueados + (bloqueados === 1 ? ' expediente bloqueado' : ' expedientes bloqueados') + ' mas de 21 dias.';
} else if (vencido > 0) {
  accion = 'Revisa las facturas vencidas: ' + eur(vencido) + ' en ' + nPend + (nPend === 1 ? ' factura pendiente' : ' facturas pendientes') + '.';
} else if (nPend > 0) {
  accion = 'Cartera al dia: ' + eur(pendiente) + ' pendiente de cobro, nada vencido.';
}

const resumen = [
  'Panel de KPIs - ' + iso(HOY),
  '',
  'COBROS',
  '- Pendiente: ' + eur(pendiente) + ' (' + nPend + ' facturas)',
  '- Vencido: ' + eur(vencido) + ' (' + r1(pctVencido) + ' %)',
  '- Cobrado en 30 dias: ' + eur(cobrado30),
  '- Salud: ' + saludCobro,
  '',
  'CLIENTES',
  '- Abiertos: ' + abiertos + ' - Completos: ' + completos + ' (tasa ' + r1(tasa) + ' %)',
  '- Documentos pendientes: ' + docsPend + ' (' + r1(pctDocs) + ' % recibidos)',
  '- Bloqueados +21 dias: ' + bloqueados,
  '',
  'ACCION: ' + accion,
].join(NL);

return [{ json: { panel: panel, historico: historico, resumen: resumen, calculado: iso(HOY) } }];

// Convierte el panel calculado en filas para la hoja KPIs (una fila por KPI).
const k = $json;
const filas = Array.isArray(k.panel) ? k.panel : [];
return filas.map(function (r) {
  return {
    json: {
      Seccion: r.Seccion || '',
      KPI: r.KPI || '',
      Valor: r.Valor,
      Unidad: r.Unidad || '',
      Detalle: r.Detalle || '',
    },
  };
});

const e = ($json.execution && $json.execution.error) ? $json.execution.error : {};
const w = ($json.workflow) ? $json.workflow.name : 'Panel de KPIs';
const nodo = ($json.execution && $json.execution.lastNodeExecuted) ? $json.execution.lastNodeExecuted : 'desconocido';
const msg = e.message ? String(e.message) : 'Error sin mensaje';
const NL = String.fromCharCode(10);
const text = [
  'ALERTA - ' + w,
  'Nodo: ' + nodo,
  'Error: ' + msg.slice(0, 500),
  'Revisa la ejecucion en n8n (Executions) para ver el detalle.',
].join(NL);
return [{ json: { text: text } }];
